import {component$, Slot} from '@builder.io/qwik';
import {useAssignedId} from './id-scope';

/**
 * Mirrors upstream's `MatError` (`src/material/form-field/directives/error.ts`).
 * `id` is normally generated by the owning `<MatFormField>` and read via
 * the `MAT_ASSIGNED_ID` context — see `mat-hint.tsx`'s doc comment for the
 * same "id ownership" note (applies identically here).
 *
 * Pass the result as `<MatFormField errors={<MatError>...</MatError>}>`
 * (or an array of them) — not as a nested child — see `mat-form-field.tsx`'s
 * doc comment for why. Whether it's actually RENDERED (vs a plain hint)
 * is `MatFormField`'s decision, driven by its `control` prop's `invalid`
 * field (see `core/mat-form-field-control.ts`) — exactly mirroring
 * upstream's `_getSubscriptMessageType()`. The CONSUMER still decides
 * WHETHER to pass a `<MatError>` at all for a given condition (mirroring
 * the Angular scenario's own `@if (nameControl.invalid) { <mat-error>...
 * </mat-error> }` — see `core/mat-form-control.ts`'s doc comment).
 */
export interface MatErrorProps {
  id?: string;
  class?: string | ReadonlyArray<string>;
}

export const MatError = component$<MatErrorProps>(props => {
  const assignedId = useAssignedId();
  const classes = [
    'mat-mdc-form-field-error',
    'mat-mdc-form-field-bottom-align',
    props.class,
  ].filter(Boolean) as string[];
  return (
    <mat-error id={props.id ?? assignedId} class={classes}>
      <Slot />
    </mat-error>
  );
});
